[DataContract]
class ISMBatchableTelemetryWorkingMemoryContract implements SysPackable
{
    private str metricName;
    private boolean logAsMetric;
    private boolean logAsEvent;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        metricName,
        logAsMetric,
        logAsEvent
    #endmacro

}

Method.Source:
[
    DataMember,
    SysOperationLabel("Metric Name"),
    SysOperationHelpText("The name of the metric to log the remaining memory as.")
]
public str parmMetricName(str _metricName = metricName)
{
    metricName = _metricName;
    return metricName;
}

[
    DataMember,
    SysOperationLabel("Log as Metric"),
    SysOperationHelpText("Indicates whether to log the remaining memory as a metric.")
]
public boolean parmLogAsMetric(boolean _logAsMetric = logAsMetric)
{
    logAsMetric = _logAsMetric;
    return logAsMetric;
}

[
    DataMember,
    SysOperationLabel("Log as Event"),
    SysOperationHelpText("Indicates whether to log the remaining memory as an event.")
]
public boolean parmLogAsEvent(boolean _logAsEvent = logAsEvent)
{
    logAsEvent = _logAsEvent;
    return logAsEvent;
}

public boolean unpack(container _packedData)
{
    int version = conPeek(_packedData, 1);
    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = _packedData;
            break;
        default:
            return false;
    }
    return true;
}
